let jsonStr = raw.trim();
const start = jsonStr.indexOf('{');
const end = jsonStr.lastIndexOf('}');
if (start !== -1 && end !== -1) jsonStr = jsonStr.slice(start, end + 1);

let data;
try { data = JSON.parse(jsonStr); }
catch (e) { data = { punteggio: 'Medio', motivo: '', stimaCollaboratori: 'incerto', prima_riga: '' }; }

const src = $('Loop · Immobiliari').item.json;
const haSito = !!(src.Sito && src.Sito.length > 5);
const attivo = (src['Recensioni Google'] || 0) >= 3;

return [{
  json: {
    ...src,
    punteggio: data.punteggio || 'Medio',
    motivo: data.motivo || '',
    stimaCollaboratori: data.stimaCollaboratori || 'incerto',
    prima_riga: data.prima_riga || '',
    priorita: (haSito && attivo) ? 'alta' : (haSito || attivo) ? 'media' : 'bassa'
  }
}];

